    public EntityList<JSONObject> aiIncidentList(HttpContext context, IncidentQueryParam param)
        throws ServiceException {

        EntityList<JSONObject> result = new EntityList<>();
        String solutionName = param.getSolutionName();

        try {
            if (!ContextUtils.getContext().getAdmin() && !checkTopoSolutionAuth(context, solutionName)) {
                LOGGER.error("[aiIncidentList] no topo solution auth: {}", solutionName);
                return result;
            }
            return getAiIncidentList(context, param);
        } catch (Exception e) {
            LOGGER.error("get AI Incident List exception ", e);
            return result;
        }
    }

    public EntityList<Incident> incidentList(IncidentQueryParam param)
        throws ServiceException {
        EntityList<Incident> result = new EntityList<>();
        param.setName(CommonUtils.escapeParam(param.getName()));
        param.setSourceObjName(CommonUtils.escapeParam(param.getSourceObjName()));

        if (Objects.isNull(param.getPaging())) {
            param.setPaging(new Paging());
        }

        List<Integer> diagnosticStatus = new ArrayList<>();
        int diagnosticType = 0;

        if (CollectionUtils.isNotEmpty(param.getDiagnosticStatus())) {
            diagnosticStatus = param.getDiagnosticStatus().stream()
                .map(DiagnosticStatusEnum::fromName)
                .map(DiagnosticStatusEnum::getCode)
                .collect(Collectors.toList());
        }

        if (StringUtils.isNotEmpty(param.getDiagnosticType())) {
            DiagnosticTypeEnum statusEnum = DiagnosticTypeEnum.fromName(param.getDiagnosticType());
            diagnosticType = statusEnum.getCode();
        }
        // 基于授权网元进行过滤
        IncidentQueryDto incidentQueryDto = new IncidentQueryDto(param);
        if (!ContextUtils.getContext().getAdmin()) {
            List<String> queryDns = getIncidentQueryDns();
            if (queryDns.isEmpty()) {
                result.setTotal(0);
            } else {
                incidentQueryDto.setDnList(queryDns);
                result.setTotal(incidentDao.getIncidentTotal(incidentQueryDto, diagnosticStatus, diagnosticType, param.getStatusList()));
            }
        } else {
            result.setTotal(incidentDao.getIncidentTotal(incidentQueryDto, diagnosticStatus, diagnosticType, param.getStatusList()));
        }
        if (result.getTotal() > 0) {
            List<Incident> incidentList = incidentDao.getIncidentList(incidentQueryDto, diagnosticStatus, diagnosticType);
            fallbackDiagnosisStatus(incidentList);
            populateEventsForIncident(incidentList);
            populateMoiForAlarmIncidents(incidentList);
            result.setObjects(incidentList);
        }
        return result;
    }

    /**
     * 获取授权网元与当前环境上单告警事件网元的交集
     *
     * @return 授权网元与当前环境上单告警事件网元的交集
     * @throws ServiceException 异常时抛出
     */
    public List<String> getIncidentQueryDns() throws ServiceException {
        List<String> queryDns = new ArrayList<>();
        Set<String> authDns = ContextUtils.getContext().getAuthDns();
        List<String> distinctDnList = incidentDao.getDistinctDnList();
        if (distinctDnList.contains(null)) {
            queryDns.add(null);
        }
        if (CollectionUtils.isEmpty(authDns) || CollectionUtils.isEmpty(distinctDnList)) {
            return queryDns;
        }
        queryDns.addAll(distinctDnList.stream().filter(Objects::nonNull).filter(authDns::contains).toList());
        return queryDns;
    }

    public void populateEventsForIncident(List<Incident> incidentList)
        throws ServiceException {
        List<Long> csns = incidentList.stream().map(Incident::getCsn).toList();
        List<Event> eventsByIncidentCsn = incidentDao.getEventsByIncidentCsn(csns);
        Map<Long, List<Event>> eventsMap =
            eventsByIncidentCsn.stream().collect(Collectors.groupingBy(Event::getIncidentCsn));
        for (Incident incident : incidentList) {
            incident.setEvents(eventsMap.get(incident.getCsn()));
        }
    }

    public void populateMoiForAlarmIncidents(List<Incident> incidentList) {
        for (Incident incident : incidentList) {
            if (ALARM.equals(incident.getCategory()) &&
                CollectionUtils.isNotEmpty(incident.getEvents())) {
                incident.setMoi(getMoiDetail(incident));
            }
        }
    }

    public ResponseResult performManualDiagnose(IncidentCsn incidentCsn)
        throws ServiceException {
        LOGGER.info("Start performManualDiagnose csn {}", incidentCsn.getIncidentCsn());
        Incident incident = incidentDao.getIncidentByCsn(incidentCsn.getIncidentCsn());

        if (!incident.getDiagnosticStatus().canPerformManualDiagnose()) {
            LOGGER.info("csn:{} is diagnosing, can't manual diagnose.", incidentCsn.getIncidentCsn());
            return ResponseResultHelper.failResponseEntity(ResourceUtil.getMessage(ExceptionInternationalConstant.INCIDENT_DIAGNOSIS_RUNNING,
                ContextUtils.getDefaultLocale()));
        }

        incident.setDiagnosticType(MANUAL);
        incident.setDiagnosticStatus(DiagnosticStatusEnum.PENDING_DIAGNOSIS);
        incidentDao.addIncident(Collections.singletonList(incident));

        try {
            MANUAL_DIAGNOSE_THREAD_POOL.execute(() -> {
                try {
                    incident.setDiagnosticStatus(DIAGNOSING);
                    incidentDao.addIncident(Collections.singletonList(incident));
                    faultDiagnosis(incident);
                    incidentDao.updateDiagnoseEndTime(incident.getCsn(), System.currentTimeMillis());
                } catch (Throwable e) {
                    incident.setDiagnosticStatus(DIAGNOSIS_FAILED);
                    try {
                        incidentDao.addIncident(Collections.singletonList(incident));
                    } catch (ServiceException ex) {
                        LOGGER.error("performManualDiagnose ServiceException csn {}", incidentCsn, ex);
                    }
                    LOGGER.error("performManualDiagnose ServiceException {}", e.getMessage(), e);
                }
            });

        } catch (RejectedExecutionException e) {
            incident.setDiagnosticStatus(DiagnosticStatusEnum.RESOURCE_INSUFFICIENT_NOT_EXECUTED);
            incidentDao.addIncident(Collections.singletonList(incident));
            LOGGER.error("performManualDiagnose RejectedExecutionException {}, csn {}", e.getMessage(), incidentCsn);
            return ResponseResultHelper.failResponseEntity("No resource");

        } catch (Exception e) {
            incident.setDiagnosticStatus(DIAGNOSIS_FAILED);
            incidentDao.addIncident(Collections.singletonList(incident));
            LOGGER.error("performManualDiagnose exception {}, csn {}", e.getMessage(), incidentCsn);
            return ResponseResultHelper.failResponseEntity("Exception");
        }

        LOGGER.info("performManualDiagnose success, csn {}", incidentCsn);
        return ResponseResultHelper.correctResponseEntity("true");
    }

    /**
     * 检查是否为LLM Engine场景
     *
     * @return bool
     * @throws ServiceException 异常时抛出
     */
    public boolean checkLlmEngineScene()
        throws ServiceException {
        Config config = configDao.getConfigByKey(LLM_ENGINE_WORKFLOW_NAME);
        if (Objects.isNull(config)) {
            LOGGER.error("llm engine workflow config not existed");
            return false;
        }
        if (!Objects.equals(config.getType(), ConfigUtils.TYPE_LLM_ENGINE_WORKFLOW)) {
            LOGGER.error("llm engine workflow config type incorrect");
            return false;
        }
        return true;
    }

    public ResponseResult faultDiagnose(HttpContext context, FaultDiagnoseParam param)
        throws ServiceException {

        boolean switchRet = checkIncidentSwitch();
        LOGGER.info("Incident switch is {}, csn {}, taskId {}", switchRet, param.getIncidentCsn(), param.getTaskId());

        if (!switchRet) {
            LOGGER.error("Incident switch is off");
            return ResponseResultHelper.failResponseEntity("NoIncidentSwitch");
        }

        Incident incident = convert2Incident(param);
        final Long csn = param.getIncidentCsn();
        final Long taskId = param.getTaskId();
        final Long startTime = param.getStartTime();
        try {

            INCIDENT_THREAD_POOL.execute(() -> {
                try {
                    FaultDiagnoseParam tempParam = new FaultDiagnoseParam();
                    tempParam.setIncidentCsn(csn);
                    tempParam.setTaskId(taskId);
                    tempParam.setStartTime(startTime);
                    IncidentReport incidentReport = incidentDiagnosisWorkflow(incident, taskId);
                    notifyLlmEngineDiagnosticResult(tempParam, incidentReport);
                } catch (Throwable e) {
                    LOGGER.error("faultDiagnosis4Incident Exception {}", e.getMessage(), e);
                }
            });

        } catch (RejectedExecutionException e) {
            LOGGER.error("RejectedExecutionException {}, param {}", e.getMessage(), param);
            return ResponseResultHelper.failResponseEntity("NoResources");

        } catch (Exception e) {
            LOGGER.error("faultDiagnose exception {}, FaultDiagnoseParam {}", e.getMessage(), param);
            return ResponseResultHelper.failResponseEntity("Exception:" + e.getMessage());
        }

        return ResponseResultHelper.correctResponseEntity("true");
    }

