    /**
     * 发送智能事件分析状态
     *
     * @param taskId 任务id
     * @param solutionName 解决方案名称
     * @param incidentCsn 事件流水号
     * @param analysisStatus 分析状态
     */
    public void sendLlmAnalysisResult(Long taskId, String solutionName, Long incidentCsn, Integer analysisStatus) {
        DiagnosisResultRequest request = new DiagnosisResultRequest();
        if (taskId != null) {
            request.setTaskId(taskId);
        }
        if (solutionName != null) {
            request.setSolutionName(solutionName);
        }
        request.setIncidentCsn(incidentCsn);
        request.setAnalysisStatus(analysisStatus);
        try {
            sendDiagnosisResult(request);
        } catch (Exception e) {
            LOGGER.error("[sendLlmAnalysisResult] Failed to send analysis status result.", e);
        }
    }

    private DiagnosisResultRequest buildLlmEngineDiagnosisResultRequest(FaultDiagnoseParam param,
        IncidentReport incidentReport) {
        DiagnosisResultRequest request = new DiagnosisResultRequest();
        request.setTaskId(param.getTaskId());
        request.setIncidentCsn(param.getIncidentCsn());
        request.setStartTime(param.getStartTime());
        String report = incidentReport.getReport().trim();
        String incidentName = incidentReport.getIncidentName().trim();
        String rootEventId = incidentReport.getRootEventId().trim();
        String handlingSuggestion = incidentReport.getHandlingSuggestion().trim();
        LOGGER.info("[buildLlmEngineDiagnosisResultRequest] incident csn={}, llmengine name={}, root event id={}",
            param.getIncidentCsn(),
            incidentName,
            rootEventId);

        if (!incidentReport.isAnalysisSuccess()) {
            request.setFailCause("Analysis failed");
            request.setGeneralRecommendation(ResourceUtil.getMessage(IncidentConstant.INCIDENT_DIAGNOSIS_ANALYSIS_FAIL));
            return request;
        }

        if (report.toLowerCase(Locale.ROOT).startsWith(Constants.MARKDOWN_PREFIX)
            && report.toLowerCase(Locale.ROOT).endsWith(Constants.MARKDOWN_SUFFIX)) {
            report = report.substring(Constants.MARKDOWN_PREFIX.length(),
                report.length() - Constants.MARKDOWN_SUFFIX.length()).trim();
        }

        request.setLlmName(incidentName);
        request.setLlmRootEventId(rootEventId);

        if (StringUtils.isNotEmpty(handlingSuggestion)) {
            String headerTitle = ResourceUtil.getMessage(IncidentConstant.INCIDENT_HANDLING_TITLE);
            report = report + "\n\n" + headerTitle + "\n" + handlingSuggestion;
        }

        if (StringUtils.isEmpty(report)) {
            request.setFailCause("Diagnosis failed");
            request.setGeneralRecommendation(ResourceUtil.getMessage(IncidentConstant.INCIDENT_DIAGNOSIS_FAIL));
            return request;
        }

        request.setFailCause("");
        request.setGeneralRecommendation("# " + incidentName + "\n\n" + report);
        return request;
    }

    /**
     * 构建诊断结果请求
     *
     * @param param 参数对象
     * @param report 诊断报告内容
     * @return 请求对象
     */
    private DiagnosisResultRequest buildDiagnosisResultRequest(FaultDiagnoseParam param, String report) {
        Locale locale = ContextUtils.getDefaultLocale();
        DiagnosisResultRequest request = new DiagnosisResultRequest();
        request.setTaskId(param.getTaskId());
        request.setIncidentCsn(param.getIncidentCsn());
        request.setStartTime(param.getStartTime());

        if (report == null) {
            request.setFailCause("Diagnosis failed");
            request.setGeneralRecommendation("");
            request.setLlmName("");
            return request;
        }
        String trimmedReport = report.trim();
        // 如果report以```markdown开头，且以```结束，需要把这两部分去掉
        if (trimmedReport.startsWith(Constants.MARKDOWN_PREFIX) && trimmedReport.endsWith(Constants.MARKDOWN_SUFFIX)) {
            trimmedReport = trimmedReport.substring(Constants.MARKDOWN_PREFIX.length(),
                trimmedReport.length() - Constants.MARKDOWN_SUFFIX.length()).trim();
        }

        int startIdx = trimmedReport.indexOf(locale.getLanguage().equalsIgnoreCase(Constants.LANG_ZH)
            ? Constants.INCIDENT_REPORT_ZH
            : Constants.INCIDENT_REPORT_EN);
        String reportBody;
        String incidentName;
        if (startIdx < 0) {
            reportBody = trimmedReport;
            incidentName = "";
        } else {
            reportBody = trimmedReport.substring(startIdx).trim();
            incidentName = trimmedReport.substring(0, startIdx).replace("#", "").trim();
            if (incidentName.contains(Constants.REPORT_TITLE_ZH)
                || incidentName.contains(Constants.REPORT_TITLE_EN)) {
                incidentName = "";
            }
        }
        LOGGER.info("incident llm name is {}", incidentName);
        request.setLlmName(incidentName);

        if (reportBody.isEmpty()) {
            request.setFailCause("Diagnosis failed");
            request.setGeneralRecommendation("");
        } else {
            request.setFailCause("");
            request.setGeneralRecommendation(reportBody);
        }

        return request;
    }

