    private void appendCheckItemsTable(StringBuilder markdown, List<CheckItem> checkItems, Locale locale) {
        markdown.append("\n\n## ")
            .append(ResourceUtil.getMessage(LogConstant.REPORT_CHECK_ITEMS, locale))
            .append("\n\n");

        markdown.append("| ").append(ResourceUtil.getMessage(LogConstant.REPORT_TABLE_SEQ, locale))
            .append(" | ").append(ResourceUtil.getMessage(LogConstant.REPORT_TABLE_ITEM, locale))
            .append(" | ").append(ResourceUtil.getMessage(LogConstant.REPORT_TABLE_STATUS, locale))
            .append(" | ").append(ResourceUtil.getMessage(LogConstant.REPORT_TABLE_DETAILS, locale))
            .append(" |\n");

        markdown.append("|----|------|--------|---------|\n");

        for (int i = 0; i < checkItems.size(); i++) {
            CheckItem item = checkItems.get(i);
            markdown.append("| ")
                .append(i + 1) // 序号从1开始
                .append(" | ")
                .append(escapeMarkdownCell(item.getName() != null ? item.getName() : ""))
                .append(" | ")
                .append(getStatusText(item.getStatus(), locale))
                .append(" | ")
                .append(escapeMarkdownCell(item.getDetails() != null ? item.getDetails() : ""))
                .append(" |\n");
        }
    }

    private static String formatTimestamp(Long timestamp) {
        if (timestamp == null || timestamp == 0L) {
            return "";
        }
        SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
        return sdf.format(new Date(timestamp));
    }

