    /**
     * 更新诊断状态和建议
     *
     * @param repairAdvice repairAdvice
     * @param latestIncident latestIncident
     * @param status 诊断状态
     * @throws ServiceException ServiceException
     */
    public void updateDiagnosis(String repairAdvice, Incident latestIncident, Integer status)
        throws ServiceException {
        LOGGER.info("[updateDiagnosis] alarm diagnosis csn={}, status={}", latestIncident.getCsn(), status);
        String diagnoseStatusDetail = ALARM_DIAGNOSE_STATUS_TO_DETAIL_MAP.get(status);
        if (diagnoseStatusDetail == null) {
            diagnoseStatusDetail = IncidentConstant.ALARM_DIAGNOSIS_GENERAL_FAIL_DETAIL;
        }
        latestIncident.setDiagnosisStatusDetail(ResourceUtil.getMessage(diagnoseStatusDetail));
        if (StringUtils.isEmpty(repairAdvice)) {
            latestIncident.setRepairAdvice(ResourceUtil.getMessage(IncidentConstant.ALARM_DIAGNOSIS_GENERAL_FAIL_DETAIL));
            latestIncident.setDiagnosticStatus(DIAGNOSIS_FAILED);
        } else if (!Objects.equals(status, IncidentConstant.ALARM_DIAGNOSIS_SUCCESS)) {
            latestIncident.setRepairAdvice(repairAdvice);
            latestIncident.setDiagnosticStatus(DIAGNOSIS_FAILED);
        } else {
            latestIncident.setRepairAdvice(repairAdvice);
            latestIncident.setDiagnosticStatus(DIAGNOSIS_SUCCESS);
        }
        List<Incident> incidentList = new ArrayList<>();
        incidentList.add(latestIncident);
        incidentDao.addIncident(incidentList);
    }

