    public IncidentStaticDto convertDtoFromEntities(List<IncidentDiagnosticCountEntity> countEntities) {
        IncidentStaticDto dto = new IncidentStaticDto();
        for (IncidentDiagnosticCountEntity entity : countEntities) {
            DiagnosticStatusEnum enumStatus = DiagnosticStatusEnum.fromCode(entity.getDiagnosticStatus());
            int cnt = entity.getCnt();
            switch (enumStatus) {
                case NOT_DIAGNOSED:
                    dto.setNotDiagnosedCnt(cnt);
                    break;
                case PENDING_DIAGNOSIS:
                    dto.setPendingDiagnosisCnt(cnt);
                    break;
                case DIAGNOSING:
                    dto.setDiagnosingCnt(cnt);
                    break;
                case DIAGNOSIS_SUCCESS:
                    dto.setDiagnosisSuccessCnt(cnt);
                    break;
                case DIAGNOSIS_FAILED:
                    dto.setDiagnosisFailed(cnt);
                    break;
                case RESOURCE_INSUFFICIENT_NOT_EXECUTED:
                    dto.setNoResourceCnt(cnt);
                    break;
                default:
                    break;
            }
        }
        return dto;
    }

    public List<Event> compressEvents(List<Event> addEvents)
        throws ServiceException {
        List<Event> filterEvents = new ArrayList<>();

        for (Event addEvent : addEvents) {
            if (!appendEventByMatchKey(addEvent)) {
                filterEvents.add(addEvent);
            }
        }

        return filterEvents;
    }

    public boolean appendEventByMatchKey(Event addEvent)
        throws ServiceException {
        Event oldEvent = incidentDao.getEventByMatchKey(addEvent.getMatchKey());

        if (oldEvent == null) {
            return false;
        }

        Incident incident = incidentDao.getIncidentByCsn(oldEvent.getIncidentCsn());

        if (truncationWindowValidator(incident, addEvent)) {
            addEvent.setIncidentCsn(incident.getCsn());
            incidentDao.addEvent(Collections.singletonList(addEvent));
            incident.setStatus(IncidentStatus.OPENED);
            incident.setClearTime(0L);
            incident.setClearStatus(0);
            incident.setEndTime(0L);
            incidentDao.addIncident(Collections.singletonList(incident));
            return true;
        }

        return false;
    }

    public boolean truncationWindowValidator(Incident incident, Event addEvent) {
        long eventOccurTime = addEvent.getOccurTime();
        long incidentOccurTime = incident.getOccurTime();
        return eventOccurTime - incidentOccurTime <= TRUNCATED_WINDOW;
    }

    @Transactional(rollbackFor = Exception.class)
    public String processAddEvent(HttpContext context, List<Event> events)
        throws ServiceException {
        // 从事件列表中筛选清除告警事件和普通告警事件
        Map<Boolean, List<Event>> classifiedEvents = events.stream()
            .collect(Collectors.partitioningBy(event -> event.getClearStatus() == CLEAR_FLAG));

        List<Event> clearedEvents = classifiedEvents.get(true);
        List<Event> normalEvents = classifiedEvents.get(false);

        if (!normalEvents.isEmpty()) {
            List<Event> addEvents = compressEvents(normalEvents);
            if (addEvents != null && !addEvents.isEmpty()) {
                List<Incident> incidents = addEvents.stream().map(event -> {
                    Incident incident = new Incident(event);
                    incident.setIncidentType(ALARM_TYPE);
                    return incident;
                }).collect(Collectors.toList());
                addIncident(context, incidents);
            }
        }

        // 处理清除告警事件
        if (!clearedEvents.isEmpty()) {
            processClearedEvents(clearedEvents);
        }

        return String.format(Locale.ENGLISH, "Events processed: %d cleared, %d uncleared", clearedEvents.size(),
            normalEvents.size());
    }

    @Transactional(rollbackFor = Exception.class)
    public void processClearedEvents(List<Event> clearedEvents)
        throws ServiceException {
        if (clearedEvents == null || clearedEvents.isEmpty()) {
            LOGGER.error("clearedEvents must not be null");
            return;
        }

        List<Event> updatedEvents = updateEventStatus(clearedEvents);
        if (CollectionUtils.isEmpty(updatedEvents)) {
            LOGGER.warn("No existing events found for source CSNs. Source count: {}", clearedEvents.size());
            return;
        }

        Set<Long> incidentCsns = extractDistinctIncidentCsns(updatedEvents);
        if (CollectionUtils.isEmpty(incidentCsns)) {
            LOGGER.info("No valid incident CSNs found in {} updated events", updatedEvents.size());
            return;
        }

        Map<Long, List<Event>> eventsByIncident = loadIncidentEvents(incidentCsns);
        Map<Long, Incident> incidentMap = loadIncidents(incidentCsns);

        List<Incident> incidentsToUpdate = processIncidentEvents(incidentCsns, eventsByIncident, incidentMap);

        updateIncidents(incidentsToUpdate);
        logProcessingSummary(clearedEvents.size(), updatedEvents.size(), incidentCsns.size(), incidentsToUpdate.size());
    }

    private Set<Long> extractDistinctIncidentCsns(List<Event> events) {
        return events.stream()
            .map(Event::getIncidentCsn)
            .filter(Objects::nonNull)
            .collect(Collectors.toCollection(LinkedHashSet::new));
    }

    private Map<Long, List<Event>> loadIncidentEvents(Collection<Long> incidentCsns)
        throws ServiceException {
        List<Event> allEvents = incidentDao.getEventsByIncidentCsn(new ArrayList<>(incidentCsns));
        LOGGER.debug("Loaded {} events for {} incidents", allEvents.size(), incidentCsns.size());
        return allEvents.stream().collect(Collectors.groupingBy(Event::getIncidentCsn));
    }

    private Map<Long, Incident> loadIncidents(Collection<Long> incidentCsns)
        throws ServiceException {
        List<Incident> incidents = incidentDao.getIncidentListByCsnList(new ArrayList<>(incidentCsns));
        if (CollectionUtils.isEmpty(incidents)) {
            LOGGER.warn("No incidents found for CSNs: {}", incidentCsns);
            return Collections.emptyMap();
        }
        return incidents.stream()
            .collect(Collectors.toMap(Incident::getCsn, Function.identity(), (oldVal, newVal) -> newVal));
    }

    private List<Incident> processIncidentEvents(Set<Long> incidentCsns,
        Map<Long, List<Event>> eventsByIncident,
        Map<Long, Incident> incidentMap) {
        List<Incident> updateList = new ArrayList<>();
        for (Long csn : incidentCsns) {
            List<Event> events = eventsByIncident.getOrDefault(csn, Collections.emptyList());
            Incident incident = incidentMap.get(csn);

            if (incident == null) {
                LOGGER.debug("Incient {} not found in loaded map", csn);
                continue;
            }

            if (isAllEventsCleared(events)) {
                updateClearedIncident(incident, events);
                updateList.add(incident);
            }
        }
        return updateList;
    }

    private boolean isAllEventsCleared(List<Event> events) {
        return !events.isEmpty() &&
            events.stream().allMatch(e -> e.getClearStatus() == CLEARED_STATUS);
    }

    private void updateClearedIncident(Incident incident, List<Event> events) {
        long clearTime = calculateLatestClearTime(events);
        incident.setClearTime(clearTime);
        incident.setEndTime(clearTime);
        incident.setClearStatus(CLEARED_STATUS);
        incident.setStatus(IncidentStatus.CLOSED);
        LOGGER.debug("Marking incident {} as cleared", incident.getCsn());
    }

    private Long calculateLatestClearTime(List<Event> events) {
        return events.stream()
            .map(Event::getClearTime)
            .filter(Objects::nonNull)
            .max(Comparator.naturalOrder())
            .orElseGet(System::currentTimeMillis);
    }

    private void updateIncidents(List<Incident> incidents)
        throws ServiceException {
        if (!incidents.isEmpty()) {
            incidentDao.addIncident(incidents);
            LOGGER.info("Updated {} incidents", incidents.size());
        }
    }

    private void logProcessingSummary(int clearedCount, int updatedCount, int incidentCount, int updateIncidentCount) {
        LOGGER.info("Processed cleared events: {}, Updated events: {}, Affected incidents: {}, Updated incidents: {}",
            clearedCount, updatedCount, incidentCount, updateIncidentCount);
    }

    private List<Event> updateEventStatus(List<Event> clearedEvents)
        throws ServiceException {
        if (CollectionUtils.isEmpty(clearedEvents)) {
            LOGGER.debug("Input cleared events list is empty");
            return Collections.emptyList();
        }

        List<Long> sourceCsns = clearedEvents.stream()
            .map(Event::getSourceCsn)
            .filter(Objects::nonNull)  // 过滤无效CSN
            .distinct()
            .collect(Collectors.toList());

        List<Event> existingEvents = incidentDao.getEventsBySouceCsnList(sourceCsns);

        handleDataSourceMismatch(sourceCsns, existingEvents);

        if (CollectionUtils.isEmpty(existingEvents)) {
            LOGGER.warn("No existing events found for provided source CSNs");
            return Collections.emptyList();
        }

        Map<Long, Event> clearedEventMap = clearedEvents.stream()
            .filter(e -> e.getSourceCsn() != null)
            .collect(Collectors.toMap(
                Event::getSourceCsn,
                Function.identity(),
                (older, newer) -> newer));

        List<Event> updatedEvents = existingEvents.stream()
            .filter(this::requiresEventStatusUpdate) // 筛选需更新的event
            .peek(event -> updateEventFromCleared(event, clearedEventMap))
            .collect(Collectors.toList());

        if (!updatedEvents.isEmpty()) {
            incidentDao.addEvent(updatedEvents);
            LOGGER.debug("Updated {} event status records", updatedEvents.size());
        }

        return updatedEvents;
    }

    private void handleDataSourceMismatch(Collection<Long> sourceCsns, List<Event> existingEvents) {
        int sourceCount = sourceCsns.size();
        int existingCount = existingEvents != null ? existingEvents.size() : 0;

        if (existingCount == 0) {
            LOGGER.warn("No events found for {} distinct source CSNs", sourceCount);
        } else if (sourceCount != existingCount) {
            LOGGER.warn("Data inconsistency: Requested CSNs: {}, Found events: {}",
                sourceCount, existingCount);
        }
    }

    private boolean requiresEventStatusUpdate(Event existingEvent) {
        return existingEvent != null && existingEvent.getSourceCsn() != null;
    }

    private void updateEventFromCleared(Event event, Map<Long, Event> clearedEventMap) {
        Event clearedEvent = clearedEventMap.get(event.getSourceCsn());
        if (clearedEvent == null) {
            LOGGER.debug("No matching cleared event for source CSN: {}", event.getSourceCsn());
            return;
        }

        event.setClearTime(clearedEvent.getClearTime());
        event.setClearStatus(clearedEvent.getClearStatus());
    }

    public List<Integer> diagnosisStatus2Int(String[] statuses) {
        List<Integer> list = new ArrayList<>();
        for (String status : statuses) {
            list.add(DiagnosticStatusEnum.fromName(status).toIncidentConstantCode());
        }
        return list;
    }

